const reduceMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
if('IntersectionObserver' in window&&!reduceMotion){document.documentElement.classList.add('motion-ready');const reveal=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');reveal.unobserve(entry.target)}})},{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>reveal.observe(el));}
document.querySelectorAll('.faq details').forEach(item=>item.addEventListener('toggle',()=>{if(item.open)document.querySelectorAll('.faq details').forEach(other=>{if(other!==item)other.open=false})}));
if('IntersectionObserver' in window){const links=[...document.querySelectorAll('nav a')];const active=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){links.forEach(link=>{const current=link.hash==='#'+entry.target.id;link.classList.toggle('active',current);if(current)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current')})}})},{rootMargin:'-20% 0px -50% 0px'});links.forEach(link=>{const section=document.querySelector(link.hash);if(section)active.observe(section)})}
const menu=document.querySelector('.mobile-menu'),nav=document.querySelector('header nav');
function closeMenu(){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Abrir menu');menu.textContent='☰'}
menu.addEventListener('click',()=>{const expanded=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(expanded));menu.setAttribute('aria-label',expanded?'Fechar menu':'Abrir menu');menu.textContent=expanded?'×':'☰'});
nav.querySelectorAll('a').forEach(link=>link.addEventListener('click',closeMenu));document.addEventListener('keydown',event=>{if(event.key==='Escape'&&nav.classList.contains('open')){closeMenu();menu.focus()}});
